import{_ as o,o as e,c as s,a5 as a}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"UC 06 — Publishing & Social (UC-83 → UC-89)","description":"","frontmatter":{},"headers":[],"relativePath":"ba/use-cases/06-publishing-social.md","filePath":"ba/use-cases/06-publishing-social.md"}'),i={name:"ba/use-cases/06-publishing-social.md"};function l(r,t,n,c,h,d){return e(),s("div",null,[...t[0]||(t[0]=[a('<h1 id="uc-06-—-publishing-social-uc-83-→-uc-89" tabindex="-1">UC 06 — Publishing &amp; Social (UC-83 → UC-89) <a class="header-anchor" href="#uc-06-—-publishing-social-uc-83-→-uc-89" aria-label="Permalink to &quot;UC 06 — Publishing &amp; Social (UC-83 → UC-89)&quot;">​</a></h1><p>&gt; <a href="./../00-overview.html">&lt;&lt; Về Overview</a> · Nguồn FR: <a href="./../07-publishing-social-collaborator.html">07-publishing-social-collaborator.md</a> &gt; Nguồn UC gốc: <code>Các FR của hệ thống - Use Case.csv</code> &gt; <strong>Phạm vi platform:</strong> Facebook, Instagram, TikTok, Threads — KHÔNG Zalo OA (loại khỏi scope).</p><h2 id="bang-tong-hop" tabindex="-1">Bảng tổng hợp <a class="header-anchor" href="#bang-tong-hop" aria-label="Permalink to &quot;Bảng tổng hợp&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UC ID</th><th>Use Case</th><th>Actor(s)</th><th>Related FR</th></tr></thead><tbody><tr><td>UC-83</td><td>Connect/Disconnect Social Account</td><td>CLIENT</td><td>3.8.1, 3.8.2</td></tr><tr><td>UC-84</td><td>View Post Dashboard</td><td>All roles (MEMBER)</td><td>3.8.3</td></tr><tr><td>UC-85</td><td>View Post Detail &amp; Comments</td><td>All roles (MEMBER)</td><td>3.8.4, 3.8.5</td></tr><tr><td>UC-86</td><td>Preview, Schedule &amp; Track Post Status</td><td>CREATOR/MANAGER</td><td>3.8.6, 3.8.7, 3.8.8</td></tr><tr><td>UC-87</td><td>Publish to Facebook</td><td>System/CREATOR</td><td>3.8.9, 3.8.10, 3.8.11</td></tr><tr><td>UC-88</td><td>Publish to Instagram</td><td>System/CREATOR</td><td>3.8.12, 3.8.13, 3.8.14</td></tr><tr><td>UC-89</td><td>Publish to TikTok &amp; Threads</td><td>System/CREATOR</td><td>3.8.15, 3.8.16</td></tr></tbody></table><hr><h2 id="uc-83-—-connect-disconnect-social-account" tabindex="-1">UC-83 — Connect/Disconnect Social Account <a class="header-anchor" href="#uc-83-—-connect-disconnect-social-account" aria-label="Permalink to &quot;UC-83 — Connect/Disconnect Social Account&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> CLIENT</li><li><strong>Description:</strong> Connect a social media account for automated posting; disconnect when needed.</li><li><strong>Precondition:</strong> Client is a Workspace member.</li><li><strong>Main Flow:</strong><ol><li>CLIENT initiates OAuth connect flow for a platform (Facebook/Instagram/TikTok/Threads).</li><li>System stores the access token, links the social account to the Workspace.</li></ol></li><li><strong>Alternate Flow:</strong><ul><li>A1. CLIENT disconnects → system revokes/removes the stored token, logs the account out.</li></ul></li></ul><h2 id="uc-84-—-view-post-dashboard" tabindex="-1">UC-84 — View Post Dashboard <a class="header-anchor" href="#uc-84-—-view-post-dashboard" aria-label="Permalink to &quot;UC-84 — View Post Dashboard&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> All roles (MEMBER)</li><li><strong>Description:</strong> View the overview dashboard of successfully published posts across the Workspace.</li><li><strong>Precondition:</strong> At least one post published.</li><li><strong>Main Flow:</strong><ol><li>User opens Post Dashboard.</li><li>System displays aggregated stats of published posts.</li></ol></li></ul><h2 id="uc-85-—-view-post-detail-comments" tabindex="-1">UC-85 — View Post Detail &amp; Comments <a class="header-anchor" href="#uc-85-—-view-post-detail-comments" aria-label="Permalink to &quot;UC-85 — View Post Detail &amp; Comments&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> All roles (MEMBER)</li><li><strong>Description:</strong> View post details (reactions, shares) and the list of comments on that post.</li><li><strong>Precondition:</strong> Post has been published.</li><li><strong>Main Flow:</strong><ol><li>User opens a specific post.</li><li>System shows reaction/share counts (Track Detail) and the full comment list (Comment Detail List).</li></ol></li></ul><h2 id="uc-86-—-preview-schedule-track-post-status" tabindex="-1">UC-86 — Preview, Schedule &amp; Track Post Status <a class="header-anchor" href="#uc-86-—-preview-schedule-track-post-status" aria-label="Permalink to &quot;UC-86 — Preview, Schedule &amp; Track Post Status&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> CREATOR/MANAGER</li><li><strong>Description:</strong> Preview post layout per platform, schedule posts, and track progress status (Pending/In Progress/Done/Fail).</li><li><strong>Precondition:</strong> Task (Post-type) has completed Approval Sequence.</li><li><strong>Main Flow:</strong><ol><li>CREATOR/MANAGER previews how the post renders per target platform.</li><li>Sets/adjusts the scheduled publish time on the posting calendar.</li><li>System queues the post; status tracked through <code>PENDING → IN_PROGRESS → DONE/FAIL</code>.</li></ol></li></ul><h2 id="uc-87-—-publish-to-facebook" tabindex="-1">UC-87 — Publish to Facebook <a class="header-anchor" href="#uc-87-—-publish-to-facebook" aria-label="Permalink to &quot;UC-87 — Publish to Facebook&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> System/CREATOR</li><li><strong>Description:</strong> Push a Post, Story, or Reels to Facebook.</li><li><strong>Precondition:</strong> Post approved and scheduled (UC-86); Facebook account connected (UC-83).</li><li><strong>Main Flow:</strong><ol><li>System dequeues the scheduled item at trigger time.</li><li>Calls Facebook Graph API to publish as Post/Story/Reels per content type.</li><li>Updates status to <code>DONE</code>.</li></ol></li><li><strong>Alternate Flow:</strong><ul><li>A1. API call fails → status <code>FAIL</code>, retry/error surfaced on the dashboard.</li></ul></li></ul><h2 id="uc-88-—-publish-to-instagram" tabindex="-1">UC-88 — Publish to Instagram <a class="header-anchor" href="#uc-88-—-publish-to-instagram" aria-label="Permalink to &quot;UC-88 — Publish to Instagram&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> System/CREATOR</li><li><strong>Description:</strong> Push a Post, Reels, or Story to Instagram.</li><li><strong>Precondition:</strong> Post approved and scheduled; Instagram account connected.</li><li><strong>Main Flow:</strong><ol><li>System dequeues the scheduled item.</li><li>Calls Instagram API to publish as Post/Reels/Story.</li><li>Updates status to <code>DONE</code>.</li></ol></li><li><strong>Alternate Flow:</strong><ul><li>A1. API call fails → status <code>FAIL</code>.</li></ul></li></ul><h2 id="uc-89-—-publish-to-tiktok-threads" tabindex="-1">UC-89 — Publish to TikTok &amp; Threads <a class="header-anchor" href="#uc-89-—-publish-to-tiktok-threads" aria-label="Permalink to &quot;UC-89 — Publish to TikTok &amp; Threads&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> System/CREATOR</li><li><strong>Description:</strong> Push a short video to TikTok and a post to Threads.</li><li><strong>Precondition:</strong> Post approved and scheduled; target account connected.</li><li><strong>Main Flow:</strong><ol><li>System dequeues the scheduled item.</li><li>Calls TikTok Content API (video) or Threads API (post) accordingly.</li><li>Updates status to <code>DONE</code>.</li></ol></li><li><strong>Alternate Flow:</strong><ul><li>A1. API call fails → status <code>FAIL</code>.</li></ul></li></ul><hr><h2 id="ghi-chu-mo-rong-—-third-party-collaborator-module-moi-chua-co-so-fr-chinh-thuc" tabindex="-1">Ghi chú mở rộng — Third-party Collaborator (module mới, chưa có số FR chính thức) <a class="header-anchor" href="#ghi-chu-mo-rong-—-third-party-collaborator-module-moi-chua-co-so-fr-chinh-thuc" aria-label="Permalink to &quot;Ghi chú mở rộng — Third-party Collaborator (module mới, chưa có số FR chính thức)&quot;">​</a></h2><p>Không thuộc 105 UC chính thức (chưa có FR number trong CSV gốc) — ghi nhận tại đây để không thất lạc khi cập nhật CSV:</p><ul><li><strong>Track Collaborator Status</strong> (đề xuất) — Manager/Creator cập nhật thủ công trạng thái hợp tác với đối tác không có API (báo điện tử, banner, TV): <code>đã liên hệ → đang đàm phán → đã chốt → đã lên sóng</code>. Gắn với 1 Media Campaign/Task cụ thể. Không tự động hóa đăng bài lên các kênh này.</li><li>Nguồn: <a href="./../07-publishing-social-collaborator.html">07-publishing-social-collaborator.md</a> §2. <strong>[OPEN QUESTION]</strong> — cần bổ sung số FR chính thức (đề xuất 3.8.17+ hoặc nhóm riêng 3.11) và thiết kế entity/DB schema khi cập nhật CSV gốc.</li></ul>',23)])])}const p=o(i,[["render",l]]);export{g as __pageData,p as default};
